 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_openStkcertIsuStatDtlWin = async function () {
    const sbmOptions = {
        id: "tx_fn_openStkcertIsuStatDtlWin",
        method: "post",
        action: "/listInvstg/newListStkcertIsuStat.do",
        ref: "dma_openStkcertIsuStatDtlWinReq",
        target: "dlt_stkcertIsu=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

